#include <cstdio>
#include <cstring>
#include <array>
#include <vector>
using namespace std;

const int MOD = 1000000007;
const int SZ = 33;
using Arr = array<array<int, SZ>, SZ>;

struct Matrix {
    Arr a;
    Matrix(bool unit = false) {
        for(auto &row: a) row.fill(0);
        if(unit) for(int i=0;i<SZ;i++) a[i][i]=1;
    }
    int* operator[](int r) { return a[r].data(); }
    const int* operator[](int r) const { return a[r].data(); }
};

int N;
Matrix operator*(const Matrix& A, const Matrix& B) {
    static long long tmp[SZ][SZ];
    memset(tmp, 0, sizeof(tmp));
    const long long LIM = 8000000000000000000LL;
    for(int k=0;k<N;k++) {
        for(int i=0;i<N;i++) {
            if(A[i][k] == 0) continue;
            for(int j=0;j<N;j++) {
                tmp[i][j] += 1LL * A[i][k] * B[k][j];
                if(tmp[i][j] >= LIM) tmp[i][j] %= MOD;
            }
        }
    }
    Matrix C;
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            C[i][j] = tmp[i][j] % MOD;
    return C;
}

Matrix shift(const Matrix& X, int d) {
    Matrix Y;
    int K = N - 1;
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) {
            int ni = (i == K) ? K : (i + d) % K;
            int nj = (j == K) ? K : (j + d) % K;
            Y[ni][nj] = X[i][j];
        }
    return Y;
}

int main() {
    long long n;
    int k;
    scanf("%lld%d", &n, &k);
    N = k + 1;
    vector<int> digits;
    while(n) {
        digits.push_back((int)(n % k));
        n /= k;
    }
    vector<Matrix> pw(100);
    for(int j=0;j<=k;j++) {
        pw[0][0][j] = 1;
        pw[0][j][j] = 1;
    }
    for(int i=1;i<(int)digits.size();i++) {
        Matrix cur(true);
        for(int j=0;j<k;j++)
            cur = cur * shift(pw[i-1], j);
        pw[i] = cur;
    }
    int add = 0;
    Matrix ans(true);
    for(int i=(int)digits.size()-1;i>=0;i--) {
        for(int j=0;j<digits[i];j++)
            ans = ans * shift(pw[i], (j + add) % k);
        add = (add + digits[i]) % k;
    }
    int ret = 0;
    for(int i=0;i<=k;i++) {
        ret += ans[i][k];
        if(ret >= MOD) ret -= MOD;
    }
    printf("%d\n", ret);
    return 0;
}
